messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low-Poly Treadmill Humanoid</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 10px;
            left: 10px;
            color: white;
            font-family: sans-serif;
            font-size: 18px;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.5);
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">Status: <span id="status-text">Standing</span></div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const CYCLE_DURATION = 10; // seconds
        const STANDBY_DURATION = 2;
        const WALK_DURATION = 3;
        const RUN_DURATION = 3;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 3, 8); // Side-on view
        camera.lookAt(0, 1.5, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- Environment ---
        // Ground (Treadmill belt)
        const groundGeo = new THREE.PlaneGeometry(50, 10);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = 0;
        ground.receiveShadow = true;
        scene.add(ground);

        // Treadmill Frame
        const frameGeo = new THREE.BoxGeometry(4, 0.5, 2);
        const frameMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const frame = new THREE.Mesh(frameGeo, frameMat);
        frame.position.set(0, -0.25, 0);
        frame.castShadow = true;
        frame.receiveShadow = true;
        scene.add(frame);

        // --- Character Construction ---
        const humanGroup = new THREE.Group();
        const skinColor = 0xFFD700; // Gold
        const shirtColor = 0xFF4500; // OrangeRed
        const pantsColor = 0x1E90FF; // DodgerBlue

        const matSkin = new THREE.MeshStandardMaterial({ color: skinColor, flatShading: true });
        const matShirt = new THREE.MeshStandardMaterial({ color: shirtColor, flatShading: true });
        const matPants = new THREE.MeshStandardMaterial({ color: pantsColor, flatShading: true });

        // Helper to create limb
        function createLimb(width, height, depth, material, x, y, z) {
            const geo = new THREE.BoxGeometry(width, height, depth);
            // Shift geometry so pivot is at top
            geo.translate(0, -height / 2, 0);
            const mesh = new THREE.Mesh(geo, material);
            mesh.position.set(x, y, z);
            mesh.castShadow = true;
            return mesh;
        }

        // Hips (Root for legs)
        const hips = new THREE.Group();
        const hipMesh = createLimb(0.6, 0.3, 0.5, matPants, 0, 0, 0);
        hips.add(hipMesh);
        humanGroup.add(hips);

        // Torso
        const torso = new THREE.Group();
        const torsoMesh = createLimb(0.7, 1.0, 0.5, matShirt, 0, 0, 0);
        torsoMesh.position.y = 0.15; // Offset from hips
        torso.add(torsoMesh);
        humanGroup.add(torso);

        // Head
        const head = createLimb(0.45, 0.45, 0.45, matSkin, 0, 0.7, 0);
        torso.add(head);

        // Shoulders
        const shoulders = new THREE.Group();
        shoulders.position.set(0, 0.5, 0); // Top of torso
        torso.add(shoulders);

        // Arms
        const leftArm = createLimb(0.2, 0.8, 0.2, matSkin, -0.4, 0, 0);
        const rightArm = createLimb(0.2, 0.8, 0.2, matSkin, 0.4, 0, 0);
        shoulders.add(leftArm);
        shoulders.add(rightArm);

        // Legs
        const leftLeg = createLimb(0.25, 0.9, 0.25, matPants, -0.25, -0.15, 0);
        const rightLeg = createLimb(0.25, 0.9, 0.25, matPants, 0.25, -0.15, 0);
        hips.add(leftLeg);
        hips.add(rightLeg);

        scene.add(humanGroup);

        // Position character on treadmill
        humanGroup.position.y = 0.15; // Hips height

        // --- Animation Logic ---
        const statusText = document.getElementById('status-text');

        function getAnimationState(time) {
            const t = time % CYCLE_DURATION;
            if (t < STANDBY_DURATION) return { phase: 'STAND', t: t, duration: STANDBY_DURATION };
            if (t < STANDBY_DURATION + WALK_DURATION) return { phase: 'WALK', t: t - STANDBY_DURATION, duration: WALK_DURATION };
            return { phase: 'RUN', t: t - STANDBY_DURATION - WALK_DURATION, duration: RUN_DURATION };
        }

        function animate(time) {
            requestAnimationFrame(animate);

            const state = getAnimationState(time);
            statusText.textContent = state.phase;

            // Normalize time within phase for smooth loops
            const tNorm = state.t / state.duration;
            const angle = tNorm * Math.PI * 2;

            // Reset to base state
            hips.rotation.x = 0;
            hips.position.y = 0;
            torso.rotation.x = 0;
            shoulders.rotation.x = 0;

            if (state.phase === 'STAND') {
                // Idle sway
                const sway = Math.sin(time * 2) * 0.02;
                torso.rotation.x = sway;
                leftArm.rotation.x = 0.1;
                rightArm.rotation.x = 0.1;
                leftLeg.rotation.x = 0;
                rightLeg.rotation.x = 0;
                hips.position.y = 0;
            } 
            else if (state.phase === 'WALK') {
                // Walking parameters
                const stride = 0.4; // Radians
                const armSwing = 0.3;
                const bob = 0.05;
                const lean = 0.05;

                // Legs
                leftLeg.rotation.x = Math.sin(angle) * stride;
                rightLeg.rotation.x = Math.sin(angle + Math.PI) * stride;

                // Arms (opposite to legs)
                leftArm.rotation.x = Math.sin(angle + Math.PI) * armSwing;
                rightArm.rotation.x = Math.sin(angle) * armSwing;

                // Body Bob (vertical movement)
                hips.position.y = Math.abs(Math.sin(angle)) * bob;

                // Slight forward lean
                torso.rotation.x = lean;
            } 
            else if (state.phase === 'RUN') {
                // Running parameters (faster frequency, larger amplitude)
                const stride = 1.2; // Radians (bigger swing)
                const armSwing = 0.8;
                const bob = 0.15;
                const lean = 0.25;
                const freq = 2; // Run is faster than walk (2 cycles per run phase vs 1 for walk)

                // Legs
                leftLeg.rotation.x = Math.sin(angle * freq) * stride;
                rightLeg.rotation.x = Math.sin(angle * freq + Math.PI) * stride;

                // Arms (tighter, faster)
                leftArm.rotation.x = Math.sin(angle * freq + Math.PI) * armSwing;
                rightArm.rotation.x = Math.sin(angle * freq) * armSwing;

                // Body Bob (more pronounced)
                hips.position.y = Math.abs(Math.sin(angle * freq)) * bob;

                // Significant forward lean
                torso.rotation.x = lean;
            }

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start Loop
        animate(0);

    </script>
</body>
</html>
```
